// Deterministic pass. Every message a rule catches is one the model never
// sees — cheaper, instant, and predictable. Rules arrive with the payload from
// the Edge Function, so they are edited in the Hub, not in this node.
const CATS = ['urgent', 'reply', 'delegate', 'archive'];
const out = [];

for (const item of items) {
  const m = item.json;
  // A mailbox whose fetch failed arrives here with no message on it. Drop it
  // rather than sending an empty shell to the model.
  if (!m || !m.gmail_id || !m.user_id) continue;

  const rules = Array.isArray(m.rules) ? m.rules : [];
  const email = String(m.sender_email || '').toLowerCase();
  const domain = email.split('@')[1] || '';
  const subject = String(m.subject || '').toLowerCase();

  // Lowest priority number wins, and the first match stops evaluation.
  const ordered = [...rules].sort((a, b) => (a.priority ?? 100) - (b.priority ?? 100));

  let hit = null;
  for (const r of ordered) {
    const v = String(r.match_value ?? '').toLowerCase();
    let match = false;
    switch (r.match_type) {
      case 'sender_email':          match = email === v; break;
      case 'sender_email_contains': match = v !== '' && email.includes(v); break;
      case 'sender_domain':         match = domain === v.replace(/^@/, ''); break;
      case 'subject_contains':      match = v !== '' && subject.includes(v); break;
      case 'is_newsletter':         match = m.is_bulk === true; break;
      case 'is_client':             match = m.is_client === true; break;
    }
    if (match && CATS.includes(r.category)) { hit = r; break; }
  }

  out.push({
    json: {
      user_id: m.user_id,
      message_id: m.message_id,
      gmail_id: m.gmail_id,
      sender_name: m.sender_name,
      sender_email: m.sender_email,
      subject: m.subject,
      preview: m.preview,
      is_bulk: m.is_bulk,
      is_client: m.is_client,
      needs_ai: !hit,
      category: hit ? hit.category : null,
      reason: hit ? ('Rule: ' + hit.name) : null,
      source: hit ? 'rules' : null,
      confidence: hit ? 1 : null,
    },
  });
}

return out;

// The HTTP node replaced the item, so the original message is read back from
// the paired input. An unparseable or failed response falls back to 'reply':
// the outcome that keeps a human looking at it.
const src = $('Apply rules').item.json;
const CATS = ['urgent', 'reply', 'delegate', 'archive'];

let parsed = {};
try {
  parsed = JSON.parse($json.choices?.[0]?.message?.content ?? '{}');
} catch (e) {
  parsed = {};
}

const raw = String(parsed.category ?? '').toLowerCase();
const category = CATS.includes(raw) ? raw : 'reply';
const failed = !CATS.includes(raw);

return {
  json: {
    user_id: src.user_id,
    message_id: src.message_id,
    gmail_id: src.gmail_id,
    category,
    reason: failed
      ? 'Needs a look — automatic sorting could not decide'
      : String(parsed.reason ?? 'Sorted by AI').slice(0, 300),
    source: 'ai',
    confidence: failed ? 0 : (typeof parsed.confidence === 'number' ? parsed.confidence : 0.5),
  },
};

// One commit call per mailbox instead of one per message.
const byUser = new Map();

for (const item of items) {
  const j = item.json;
  if (!j.user_id || !j.category) continue;
  if (!byUser.has(j.user_id)) byUser.set(j.user_id, []);
  byUser.get(j.user_id).push({
    message_id: j.message_id,
    gmail_id: j.gmail_id,
    category: j.category,
    reason: j.reason,
    source: j.source,
    confidence: j.confidence,
  });
}

return [...byUser.entries()].map(([user_id, results]) => ({ json: { user_id, results } }));

